<?php
/** @noinspection PhpUnhandledExceptionInspection */
declare(strict_types=1);

// Test generated by Claude Code.

namespace Tests\Product\Action\Query;

use Module\Product\Action\Dto\ProductShortDto;
use Module\Product\Action\Query\GetProductByEansQry;
use Module\Product\Model\Product;
use Module\Product\Model\ProductRepository;
use PHPUnit\Framework\Attributes\DataProvider;
use PHPUnit\Framework\Attributes\Test;
use Tests\IntegrationTestCase;

class GetProductByEansQryTest extends IntegrationTestCase
{
    private GetProductByEansQry $sut;

    private ProductRepository $productRepository;

    public function setUp(): void
    {
        parent::setUp();

        $this->productRepository = $this->container->get(ProductRepository::class);

        $this->sut = new GetProductByEansQry(
            $this->productRepository->getEntityManager()
        );
        $this->prepareDb();
    }

    /**
     * @param string[]          $eans
     * @param ProductShortDto[] $expected
     */
    #[Test, DataProvider('dataProviderHandle')]
    public function handle(
        array $eans,
        array $expected,
    ): void {
        $result = $this->sut->handle($eans);

        $this->assertEqualsCanonicalizing($expected, $result);
    }

    /**
     * @return array<string, array<string, mixed>>
     */
    public static function dataProviderHandle(): array
    {
        return [
            'empty input returns empty array' => [
                'eans' => [],
                'expected' => [],
            ],
            'single matching ean' => [
                'eans' => ['ean-1'],
                'expected' => [new ProductShortDto(100, 'ean-1')],
            ],
            'multiple matching eans' => [
                'eans' => ['ean-1', 'ean-2'],
                'expected' => [
                    new ProductShortDto(100, 'ean-1'),
                    new ProductShortDto(101, 'ean-2'),
                ],
            ],
            'unknown ean returns empty array' => [
                'eans' => ['ean-unknown'],
                'expected' => [],
            ],
            'mix of known and unknown eans returns only matches' => [
                'eans' => ['ean-1', 'ean-unknown'],
                'expected' => [new ProductShortDto(100, 'ean-1')],
            ],
        ];
    }

    private function prepareDb(): void
    {
        $this->productRepository->saveWithId(Product::factory('ean-1', 'Red square', 'red-square.png', 100));
        $this->productRepository->saveWithId(Product::factory('ean-2', 'Blue circle', null, 101));
        $this->productRepository->flush();
    }
}
